from taf.internal.nidd import NIDDRemoteAPI
from .configuration import ModelConfig
import json
from lxml import etree


class PackageAlreadyExists(Exception):
    pass


class ManagedObjectAlreadyExists(Exception):
    pass


class ManagedObjectDataIncorrect(Exception):
    pass


class ParameterObjectAlreadyExists(Exception):
    pass


class NiddData(object):
    """

    """
    def __init__(self, domain, product):
        self.domain = domain
        self.product = product
        self.packages = {}

    def add_package(self, name, package_id):
        if package_id not in self.packages:
            self.packages[package_id] = NiddPackage(
                domain=self.domain,
                product=self.product,
                name=name,
                package_id=package_id
            )
        else:
            raise PackageAlreadyExists("Package name {} already exists in NiddData".format(name))


class NiddPackage(object):
    """
    NiddPackage object contains data and managedObjects of given package_id
    Can be loaded with .update method from Standard XML Report API NIDD
    """
    def __init__(self, domain, product, name, package_id):
        self.domain = domain
        self.product = product
        self.name = name
        self.package_id = package_id
        self.managed_objects = {}

    def add_managed_object(self, managed_object):
        if managed_object.class_name in self.managed_objects:
            raise ManagedObjectAlreadyExists("Managed object {} already exists in NiddPackage {}".format(
                managed_object.class_name, self.name)
            )

        self.managed_objects[managed_object.class_name] = managed_object

    def __get_xml_data(self, package_raw_data):
        return etree.XML(package_raw_data)

    def __get_managed_objects_data(self, package_xml_data):
        return package_xml_data.xpath("//managedObject")

    def update(self):
        """
        Loads data for given package from via Standard XML Report NIDD API and creates NiddManagedObject
        objects based on the data.
        """
        nidd_api = NIDDRemoteAPI(ModelConfig.nidd_api_address)
        package_raw_data = nidd_api.report.parameters(package_id=self.package_id)
        package_xml_data = self.__get_xml_data(package_raw_data)

        managed_objects_data = self.__get_managed_objects_data(package_xml_data)

        for managed_object_data in managed_objects_data:
            if managed_object_data.get("class") == "SFP":
                """
                Nasty workaround - for which the author feels ashamed - it is needed,
                because currently SFP MOCs in NIDD are broken, there are three objects with the same class/MOC name
                this is not in line with NIDD CM modeling process, and discussion is ongoing.
                Hopefully we will see the end of it before anyone notices this code.
                """
                continue

            managed_object = NiddManagedObject(
                class_name=managed_object_data.get("class"),
                domain=self.domain,
                product=self.product,
                package_name=self.name,
                package_id=self.package_id,
            )
            managed_object.update_model_from_xml(xml_data=managed_object_data)
            self.add_managed_object(managed_object)


class NiddManagedObject(object):

    def __init__(self, class_name, domain, product, package_name, package_id=None, name=None):
        """
        NiddModel creation based on provided parameters.
        Converts list of parameter data into keyword accessible parameters structure - based on paramAbbr value.
        FDEV: TO BE MOVED TO: taf.internal.datamodel.nidd

        :param name: Name of the nidd model
        :param domain: Nidd domain name
        :param product: Nidd product name
        :param package_name: Nidd package version name
        """
        if name is None:
            name = class_name

        self.class_name = class_name
        self.name = name
        self.domain = domain
        self.product = product
        self.package_name = package_name
        self.parameters = {}
        self.package_id = package_id
        self.__related_child_managed_object_list = []

    def __create_parameter_from_dict(self, data):
        """
        Handles data from Basic Parameters api
        :param data: Dictionary with parameter attributes
        :return: dictionary with parameter objects
        """
        keyword_parameters = dict()
        for parameter in data:
            attributes = {
                "moc_name": parameter['MocName'],
                "package_name": parameter['PackageName'],
                "data_type_name": parameter['DataTypeName'],
                "package_id": parameter['PackageId'],
                "param_name": parameter['ParamName'],
                "status_name": parameter['StatusName'],
                "id": parameter['Id']
            }

            if attributes["data_type_name"] == "Structure":
                # NIDD JSON API specific "Structure" name means complexType in NIDD XML API
                new_parameter = NiddComplexParameter(param_abbr=parameter["ParamAbbr"], **attributes)
            else:
                new_parameter = NiddParameter(param_abbr=parameter["ParamAbbr"], **attributes)

            keyword_parameters[new_parameter.param_abbr] = new_parameter
        return keyword_parameters

    def update_model_from_api(self):
        """
        Query NIDD API based on model parameters, get all pages and parameters, update model parameters
        """
        page_number = 1
        parameter_list = list()
        nidd_api = NIDDRemoteAPI(ModelConfig.nidd_api_address)

        while page_number < ModelConfig.max_page:
            response = nidd_api.parameter.search(
                domain=self.domain,
                product=self.product,
                moc_name=self.name,
                package_name=self.package_name,
                limit=ModelConfig.page_size,
                page=page_number
            )

            parameters = json.loads(response)
            if len(parameters):
                parameter_list = parameter_list + parameters
            else:
                break
            page_number = page_number + 1

        if len(parameter_list):
            self.package_id = parameter_list[-1]["PackageId"]

        self.parameters.update(self.__create_parameter_from_dict(data=parameter_list))

    def __create_parameter_from_xml(self, data):
        """
        Creates NiddParameter or NiddComplexParameter objects based on data from XML.
        :param data: XML Element data of NIDD parameter object
        :return: NiddParameter or NiddComplexParameter
        """

        attributes = dict(
            id=data.get("id"),
            param_abbr=data.get("name"),
            moc_name=self.name,
            package_name=self.package_name,
            package_id=data.get("releaseId"),
            param_name=data.get("fullName"),
            status_name=data.get("status"),
            class_name=self.class_name
        )

        complex_type_data = data.find("complexType")

        if complex_type_data is not None:
            nidd_parameter = NiddComplexParameter(
                data_type_name="Structure",
                **attributes
            )

            for sub_parameter_data in complex_type_data.iterchildren(tag="p"):
                nidd_sub_parameter = self.__create_parameter_from_xml(data=sub_parameter_data)
                nidd_parameter.add_parameter(parameter=nidd_sub_parameter)
        else:
            simple_type_data = data.find("simpleType")
            editing_data = simple_type_data.find("editing")

            if editing_data is not None:
                type_value_data = editing_data
            else:
                type_value_data = simple_type_data

            default_value = self.__get_default_value(type_value_data)
            if default_value is not None:
                attributes["default_value"] = default_value

            nidd_parameter = NiddParameter(
                data_type_name=simple_type_data.get("base"),
                **attributes
            )

        return nidd_parameter

    def __get_default_value(self, type_value_data):
        default_data = type_value_data.find("default")

        if default_data is not None:
            default_data_value = default_data.get("value")

            if type_value_data.find("enumeration") is None:
                return default_data_value
            else:
                return self.__get_enum_value(type_value_data, default_data_value)

    def __get_enum_value(self, simple_type_data, expected):
        for enum_object in simple_type_data.iterchildren(tag="enumeration"):
            if enum_object.get("value") == expected:
                return enum_object.get("text")
        return NiddParameter.CorruptedValue("Enumeration index does not correspond to any value")

    def update_model_from_xml(self, xml_data):
        """
        Update NiddManagedObject attributes and parameters from advanced Standard XML Report NIDD API loaded in NiddPackage
        :param xml_data: XML Element data of managedObject
        """
        if self.class_name != xml_data.get("class", None):
            raise ManagedObjectDataIncorrect(
                "managedObject xml data does not belong to managed object you are trying to update"
            )

        for child_managed_object in xml_data.iterchildren(tag="childManagedObject"):
            self.__related_child_managed_object_list.append(child_managed_object.get("class"))

        for parameter_data in xml_data.iterchildren(tag="p"):
            nidd_parameter = self.__create_parameter_from_xml(data=parameter_data)
            self.parameters[nidd_parameter.param_abbr] = nidd_parameter


class NiddParameter(object):
    """
    Nidd Parameter representing simpleType object in NIDD.
    By default parameter attributes are not entirely loaded and have NiddParameter.NotLoaded value

    Basic load from Managed Object Basic API (JSON NIDD):
        id
        moc_name
        package_name
        param_abbr
        data_type_name
        package_id
        param_name
        status_name
        class_name

    Advanced load from Managed Object XML API (XML NIDD):
        value_range
        default_value
    """
    class NotLoaded(object):
        pass

    class CorruptedValue(object):
        def __init__(self, reason):
            self.reason = reason

    def __init__(self, param_abbr, **parameter_attributes):
        self.id = self.NotLoaded
        self.moc_name = self.NotLoaded
        self.package_name = self.NotLoaded
        self.param_abbr = param_abbr
        self.data_type_name = self.NotLoaded
        self.package_id = self.NotLoaded
        self.param_name = self.NotLoaded
        self.status_name = self.NotLoaded
        self.default_value = self.NotLoaded
        self.value_range = self.NotLoaded
        self.class_name = self.NotLoaded

        self.__update_attributes(parameter_attributes=parameter_attributes)

    def __update_attributes(self, parameter_attributes):
        for attribute in parameter_attributes:
            if hasattr(self, attribute):
                setattr(self, attribute, parameter_attributes.get(attribute))


class NiddComplexParameter(NiddParameter):
    """
    Nidd Parameter representing complexType object in NIDD.
    See NiddParameter doc for more detauls about attributes.

    Contains dictionary map of other NiddParameter objects in parameters attribute
    """

    def __init__(self, param_abbr, **parameter_attributes):
        super(NiddComplexParameter, self).__init__(param_abbr=param_abbr, **parameter_attributes)
        self.parameters = {}

    def add_parameter(self, parameter):
        if parameter.param_abbr in self.parameters:
            raise ParameterObjectAlreadyExists("Parameter object already exists in parameters")

        self.parameters[parameter.param_abbr] = parameter
